static int update = 0;
for (size_t i = 0; i < n; i++) {
    char *got  = capture_run(inputs[i]);            /* stdout + produced files */
    char *want = read_file(golden_path(inputs[i]));
    if (update)
        write_file(golden_path(inputs[i]), got);   /* review the diff, then commit */
    else
        assert_string_equal(want, got);            /* cmocka prints the mismatch */
    free(got);
    free(want);
}
